}

export function sessionsProjectionOptionalText(
  value: string | undefined,
  max: number,
): string | undefined {
  if (typeof value !== 'string' || !Number.isSafeInteger(max) || max <= 0) {
    return undefined
  }
  const clean = [...value]
    .map((character) => {
      const code = character.charCodeAt(0)
      return code <= 31 || code === 127 ? ' ' : character
    })
    .join('')
    .trim()
    .slice(0, max)
